script:
frappe.ui.form.on("ToDo", {
    refresh(frm) {

        frm.add_custom_button("Create Task", function () {

            let d = new frappe.ui.Dialog({
                title: "Create Task",
                fields: [
                    {
                        label: "Task Subject",
                        fieldname: "task_subject",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],
                primary_action_label: "Create Task",
                primary_action(values) {

                    frappe.call({
                        method: "practice_app.api.create_task",
                        args: {
                            task_subject: values.task_subject
                        },
                        callback: function (r) {

                            d.hide();

                            frappe.msgprint({
                                title: "Success",
                                indicator: "green",
                                message: "Task Created Successfully<br>Task: " + r.message
                            });

                        }
                    });

                }
            });

            d.show();

        });

    }
});

frappe.listview_settings['Workspace'] = {
	refresh: function(listview) {
		listview.page.set_primary_action(__('Add Workspace'), function() {
			frappe.new_doc('Workspace');
		});
	}
};

frappe.ui.form.on("Course", {
    refresh(frm) {

        frm.add_custom_button("Enter Course Name", function () {

            let dialog = new frappe.ui.Dialog({
                title: "Enter Course Name",

                fields: [
                    {
                        label: "Course Name",
                        fieldname: "course_name",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],

                primary_action_label: "Create Course",

                primary_action(values) {

                    dialog.hide();

                    frappe.route_options = {
                        course_name: values.course_name
                    };

                    frappe.new_doc("Course");
                }
            });

            dialog.show();
        });
    }
});

frappe.ui.form.on("Task", {
    refresh(frm) {
        frm.add_custom_button("Create Task", function() {
            let dialog = new frappe.ui.Dialog({
                title: "Create New Task",
                fields: [
                    {
                        label: "Task Subject",
                        fieldname: "task_subject",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],
                primary_action_label: "Create Task",
                primary_action(values) {
                    frappe.call({
                        method: "practice_app.api.create_task",
                        args: {
                            task_subject: values.task_subject
                        },
                        callback: function(r) {
                            dialog.hide();
                            frappe.msgprint({
                                title: "Success",
                                message: "Task created successfully: " + r.message,
                                indicator: "green"
                            });
                        }
                    });
                }
            });
            dialog.show();
        });
    }
});

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', function() {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
